import { attrtypeList, attrSave, attrDetail } from "@/api/system/ciModel";
import { validatorSearch } from "@/api/system/checkRulesManage";
import enumForm from "./arrtFormConfig/enumForm";
import selectForm from "./arrtFormConfig/selectForm";
import datetimeForm from "./arrtFormConfig/datetimeForm";
import datetimerangeForm from "./arrtFormConfig/datetimerangeForm";
import fileForm from "./arrtFormConfig/fileForm";
import tableForm from "./arrtFormConfig/tableForm";
import expressionForm from "./arrtFormConfig/expressionForm";
import hyperlinkForm from "./arrtFormConfig/hyperlinkForm";
export default {
  components: {
    enumForm: enumForm,
    selectForm: selectForm,
    datetimeForm: datetimeForm,
    fileForm: fileForm,
    tableForm: tableForm,
    expressionForm: expressionForm,
    hyperlinkForm: hyperlinkForm,
    datetimerangeForm: datetimerangeForm
  },
  props: ["isShow", "ciId", "showType", "arrtId"],
  data: function data() {
    return {
      submitForm: {},
      rules: {
        name: [{
          required: true,
          message: '唯一标识不能为空',
          trigger: 'blur'
        }],
        label: [{
          required: true,
          message: '名称不能为空',
          trigger: 'blur'
        }],
        type: [{
          required: true,
          message: '类型不能为空',
          trigger: 'blur'
        }]
      },
      typeRadioList: [],
      validatorList: [],
      saveLoading: false
    };
  },
  mounted: function mounted() {
    this.getDict();
    this.getDeatil();
  },
  methods: {
    getDeatil: function getDeatil() {
      var _this = this;
      if (this.showType != '新增') {
        attrDetail({
          id: this.arrtId
        }).then(function (res) {
          _this.submitForm = res.Return;
        });
      }
    },
    getDict: function getDict() {
      var _this2 = this;
      attrtypeList().then(function (res) {
        _this2.typeRadioList = res.Return;
      });
      validatorSearch({
        needPage: false
      }).then(function (res) {
        _this2.validatorList = res.Return.tbodyList;
      });
    },
    save: function save() {
      var _this3 = this;
      this.$refs.submitForm.validate(function (valid) {
        if (valid) {
          _this3.saveLoading = true;
          _this3.submitForm.ciId = _this3.ciId;
          attrSave(_this3.submitForm).then(function (res) {
            _this3.$message({
              type: 'success',
              message: '保存成功！'
            });
            _this3.$emit('saveArrt');
            _this3.saveLoading = false;
          }).catch(function () {
            _this3.saveLoading = false;
          });
        }
      });
    }
  }
};
